import sys, zipfile, os
zip_path = sys.argv[1]

def parse_fasta(text):
    seqs = []
    cur_id = None
    cur_seq = []
    for line in text.split('\n'):
        line = line.strip()
        if line.startswith('>'):
            if cur_id is not None:
                seqs.append((cur_id, ''.join(cur_seq)))
            cur_id = line[1:]
            cur_seq = []
        elif line:
            cur_seq.append(line)
    if cur_id is not None:
        seqs.append((cur_id, ''.join(cur_seq)))
    return seqs

def count_pis(seqs):
    if not seqs:
        return 0, 0
    L = len(seqs[0][1])
    pis = 0
    for col in range(L):
        chars = {}
        for _, s in seqs:
            c = s[col]
            if c != '-':
                chars[c] = chars.get(c, 0) + 1
        if sum(1 for cnt in chars.values() if cnt >= 2) >= 2:
            pis += 1
    return pis, L

with open('results.tsv', 'w') as out:
    out.write('gene\tparsimony_informative_sites\ttotal_sites\tpercentage\n')
    with zipfile.ZipFile(zip_path) as zf:
        names = sorted(n for n in zf.namelist() if n.endswith('.mafft'))
        for name in names:
            gene = os.path.basename(name).replace('.faa.mafft', '')
            content = zf.read(name).decode('utf-8')
            seqs = parse_fasta(content)
            pis, total = count_pis(seqs)
            pct = (pis / total * 100) if total > 0 else 0
            out.write(f'{gene}\t{pis}\t{total}\t{pct:.4f}\n')
PYEOF

